import hashlib, os, shlex, sys
from pathlib import Path
COMPILER=os.path.realpath("/usr/bin/x86_64-linux-gnu-g++-13")
REQUIRED=("-static","-static-libgcc","-static-libstdc++")
DIRECT_DYNAMIC={"-shared","-dynamic","-Bdynamic","-pie","-static-pie","-rdynamic","--dynamic-linker"}
def reject(message): raise ValueError(message)
def validate_link_file(link_file,build_root,target):
    root=Path(build_root).resolve(strict=True)
    expected=(root/"CMakeFiles"/(target+".dir")/"link.txt").resolve(strict=True)
    supplied=Path(link_file)
    if supplied.is_symlink() or not supplied.is_file(): reject("link.txt must be a regular non-symlink file")
    actual=supplied.resolve(strict=True)
    if actual!=expected: reject("link.txt path is not the expected target file")
    try: actual.relative_to(root)
    except ValueError: reject("link.txt escapes build root")
    content=actual.read_text(encoding="utf-8")
    try: argv=shlex.split(content,posix=True)
    except ValueError: reject("malformed link command quoting")
    if not argv or os.path.realpath(argv[0])!=COMPILER: reject("linker compiler identity mismatch")
    if any(x.startswith("@") for x in argv): reject("response files unsupported")
    if any(x=="-Wl" or x.startswith("-Wl,") or x=="-Xlinker" or x.startswith("-Xlinker") for x in argv): reject("forwarded linker controls unsupported for this target")
    if any(x in DIRECT_DYNAMIC or x.startswith("--dynamic-linker=") for x in argv): reject("direct dynamic-link override")
    if any(argv.count(flag)!=1 for flag in REQUIRED): reject("each static-link token must occur exactly once")
    return {"status":"PASS","link_file_sha256":hashlib.sha256(actual.read_bytes()).hexdigest(),"compiler":argv[0]}
if __name__=="__main__":
    try: print(validate_link_file(sys.argv[1],sys.argv[2],sys.argv[3]))
    except Exception as exc: print("link check failed: "+str(exc),file=sys.stderr); raise SystemExit(2)
